style.css:
@-moz-document domain("genius.com") {
:root { color-scheme: dark !important; }

  /* ====================================================================
     Base surfaces  (both React + legacy "snarly" pages use <body>)
     ==================================================================== */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  /* legacy page body variants paint #f7f7f7 / white */
  body.snarly, body[class*="cont-"], body.act-show { background-color: #14181d !important; }

  /* Soften every default light border to a subtle dark line */
  * { border-color: #262c33 !important; }

  /* Login / Sign-up hero: the page grid paints a decorative gradient (and, since the
     auth redesign, a solid white background-color) that washes the whole auth screen
     and hides the light "Sign In"/"Sign Up" title. Pin it to the dark base.
     NOTE: PageGrid-desktop is NOT only a layout wrapper. On a song page the
     annotation portal's grid carries the same class (AnnotationPortal-desktop__Grid):
     it is position:absolute, z-index:2, pointer-events:none and natively transparent,
     used solely to position the callout. Painting it opaque buries the entire lyrics
     column the moment an annotation opens. The exception below must stay. */
  [class*="PageGrid-desktop"] {
    background-color: #14181d !important; background-image: none !important; }

  /* Annotation portal grid: transparent overlay, must never be painted. */
  [class*="AnnotationPortal-desktop__Grid"] {
    background-color: transparent !important; }

  /* MOBILE song page: the About + Q&A band is a "PageGrid-mobile" ("About__Grid") the
     site paints with the brand hero gradient (#ca4e45 -> #8b7e85) and black copy. The
     rule above only matches "PageGrid-desktop", so on the mobile bundle a ~4000px
     salmon slab survives and our lifted light copy lands on it at ~2.5:1. Pin it to the
     dark base. It is an in-flow section grid (not the pointer-events:none portal
     overlay), so painting it is safe; on desktop the same grid is natively bare. */
  [class*="About__Grid"] {
    background-color: #14181d !important; background-image: none !important; }

  /* Mobile annotation reader: tapping a referent opens a ReactModal whose outer
     "Modal-mobile__Contents" is already darkened, but the inner annotation panel
     "BaseAnnotation-mobile__Container" ships pure white. Our typography lifts its
     body copy to light, so the whole annotation reads as light-on-white — nearly
     invisible. Darken the panel to the modal tone. The DESKTOP counterpart
     ("BaseAnnotation-desktop__Container") is natively transparent (it sits in the
     dark sidebar) and must stay untouched, so this is scoped to the mobile class. */
  [class*="BaseAnnotation-mobile__Container"] {
    background-color: #14181d !important; }
  /* The same mobile annotation reader shows the annotated lyric at the top as an
     "AnnotationLyrics__FragmentHighlight" — a pure-white highlight box with a light
     outline. Our ReferentFragment rules use a different class, so it stays white and the
     lifted light lyric text lands on white. Match the elevated referent tone, lift the
     text, and drop the light outline the modal draws around the lyric block. */
  [class*="AnnotationLyrics__FragmentHighlight"] {
    background-color: #21262d !important; color: #e6edf3 !important; }
  [class*="AnnotationLyrics__Container"],
  [class*="AnnotationLyrics__FragmentHighlight"] {
    outline-color: #2d333b !important; }

  /* Sign-in / Sign-up modal (nav "Sign Up", mobile menu): the panel is a brand-yellow
     card with black copy. Our lifted light text lands on the yellow at ~1.5:1, so the
     title, the "Or Sign Up with Email" divider and the terms line all disappear.
     Darken the card like every other floating surface; the copy is already light. */
  [class*="AuthenticationModal__Container"],
  [class*="Modal-desktop__Contents"], [class*="Modal-mobile__Contents"] {
    background-color: #14181d !important; background-image: none !important; }
  /* the "Join millions of contributors…" strapline is a plain <div> the site paints pure
     black (fine on the yellow card, invisible once it is dark) — the shared typography
     list only covers inline/text tags, so name it explicitly */
  [class*="AuthenticationFormComponents__Reason"],
  [class*="AuthenticationModal__Container"] div { color: #c4cdd6 !important; }

  /* ====================================================================
     MODERN (React / styled-components) shell
     ==================================================================== */

  /* ---- Sticky top nav: the site's brand bar (yellow on most pages, brand red on
     song pages) -> dark with a red accent ---- */
  [class*="StickyNav-desktop__Container"],
  [class*="StickyNav__Container"],
  [class*="StickyNav-mobile__Container"],
  [class*="StickyNavMobile"] {
    background-color: #0d1117 !important;
    border-bottom: 2px solid #ed4337 !important;
    color: #e6edf3 !important; }
  [class*="StickyNav-desktop__Subnavigation"],
  [class*="StickyNavSiteLinks"],
  [class*="StickyNav-desktop__Left"],
  [class*="StickyNav-desktop__Right"] { background-color: transparent !important; }
  [class*="StickyNavSectionLink__StyledLink"],
  [class*="StickyNav-desktop__AuthTextButton"],
  [class*="StickyNav-desktop__Auth"],
  [class*="StickyNav"] a { color: #e6edf3 !important; }
  /* the "Sign Up" text button (login/signup pages) ships black text -> lift both
     color and the webkit text-fill so it stays legible on the dark nav */
  [class*="StickyNav-desktop__AuthCustomTextButton"],
  [class*="StickyNav-desktop__AuthCustomTextButton"] * {
    color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }
  [class*="StickyNavSectionLink__StyledLink"]:hover,
  [class*="StickyNav"] a:hover { color: #ffffff !important; }
  /* Mobile hamburger menu: the flyout is a full-screen BRAND-YELLOW panel with black
     links and black social glyphs. Our nav rules lift the links to near-white, so on the
     yellow they land at ~1.2:1 and every menu item disappears. It only exists once the
     hamburger is tapped (and only on the mobile bundle), so no load-time scan sees it.
     Darken the panel like every other floating surface and lift the black glyphs. */
  [class*="StickyNav-mobile__Navigation"],
  [class*="StickyNavSiteLinks__MobileContainer"] {
    background-color: #14181d !important; }
  [class*="SocialLinks__Link"] svg, [class*="SocialLinks__Link"] svg path {
    fill: #c4cdd6 !important; }
  /* Every nav section link ships "border: 1px solid transparent" and the CURRENT section
     turns that border white — it is the only "you are here" cue. The blanket border reset
     paints all four sides of every link, so the whole nav renders as grey boxes and the
     active tab becomes indistinguishable. Clear them, then repaint the active one. */
  [class*="StickyNavSectionLink__StyledLink"] { border-color: transparent !important; }
  [class*="StickyNavSectionLink__StyledLink"][data-active="true"] {
    border-color: #ed4337 !important; color: #ffffff !important; }
  /* GENIUS wordmark: the inline SVG fill is black on some pages (home/charts) ->
     force light so it's visible on the dark header across all page types */
  [class*="PageHeaderLogo__Link"] svg, [class*="StickyNav-desktop__Logo"] svg,
  [class*="VideoListLogo__Link"] svg, [class*="PageHeaderLogo"] svg,
  [class*="PageHeaderLogo__Link"] svg path, [class*="StickyNav-desktop__Logo"] svg path,
  [class*="VideoListLogo__Link"] svg path, [class*="PageHeaderLogo"] svg path,
  [class*="PageHeaderLogo__Link"] svg use, [class*="PageHeaderLogo"] svg use,
  [class*="PageHeaderLogo__Link"] svg polygon, [class*="PageHeaderLogo"] svg polygon {
    fill: #e6edf3 !important; color: #e6edf3 !important; }
  /* nav search field */
  [class*="StickyNavSearch-desktop__Form"],
  [class*="StickyNavSearch"][class*="Form"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="StickyNavSearch-desktop__Input"],
  [class*="StickyNavSearch"][class*="Input"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  [class*="StickyNavSearch"] [class*="Input"]::placeholder { color: #8b949e !important; }
  [class*="StickyNavSearch-desktop__Icon"] svg,
  [class*="StickyNavSearch"] svg { fill: #c4cdd6 !important; color: #c4cdd6 !important; }
  /* Pageview eye icon (song rows / mini-cards / charts): eye.svg ships no fill on
     its paths, so it defaults to black and vanishes on the dark card. It sits right
     next to the pageview count; follow currentColor so it matches that count. */
  svg[src="eye.svg"], svg[src="eye.svg"] path {
    fill: currentColor !important; }
  /* nav search autocomplete dropdown: a white floating panel by default. Its
     result rows render in a same-origin genius.com/search/embed iframe, so the
     card/text rules below also apply inside it via @-moz-document. */
  [class*="PageHeaderDropdownMenu"],
  [class*="SearchDropdown"], [class*="search_dropdown"],
  .search_results, .quick_search-results {
    background-color: #1c2128 !important; border-color: #2d333b !important; color: #e6edf3 !important; }
  /* "Sign Up" is a zero-padding TEXT button on the live site, so painting it a
     solid brand-red box wraps the glyphs in a tight red rectangle (and white on
     #ed4337 is only 3.85:1). Keep it a text button and carry the brand red in
     the label, lifted so it clears 4.5:1 on the dark nav. */
  [class*="StickyNavSignUp__Button"],
  [class*="StickyNavSignUp__Button"] * {
    background-color: transparent !important; border-color: transparent !important;
    color: #f26659 !important; -webkit-text-fill-color: #f26659 !important; }
  [class*="StickyNavSignUp__Button"]:hover,
  [class*="StickyNavSignUp__Button"]:hover * {
    color: #ff8a7d !important; -webkit-text-fill-color: #ff8a7d !important; }

  /* ---- Song hero: bright-red gradient -> deep dark gradient w/ red tint ---- */
  [class*="SongHeader-desktop__Container"],
  [class*="SongHeader__Container"],
  [class*="SongHeader-mobile__Container"] {
    background-color: #14181d !important;
    background-image: linear-gradient(#1c2128, #14181d) !important;
    border-bottom: 1px solid #2d333b !important;
    color: #e6edf3 !important; }
  [class*="SongHeader-desktop__Title"],
  [class*="SongHeader"][class*="Title"] { color: #ffffff !important; }
  [class*="SongHeader-desktop__SongDetails"],
  [class*="SongHeader-desktop__Information"],
  [class*="SongHeader"] [class*="Credit"],
  [class*="SongHeader"] [class*="MetadataStats"] { color: #c4cdd6 !important; }

  /* ====================================================================
     Typography (shared)
     ==================================================================== */
  h1, h2, h3, h4, h5, h6,
  [class*="SectionTitle__Title"], [class*="LyricsHeader__Title"],
  [class*="SongInfo__Title"], [class*="RecommendedSongs__Header"],
  [class*="Comments__Title"], [class*="QuestionList__Header"],
  [class*="PrimaryAlbum__Title"], [class*="ContributorsCreditSong__Label"] {
    color: #e6edf3 !important; }
  p, li, dd, dt, span, td, th, label, figcaption, time, small, blockquote,
  [class*="RichText__Container"], [class*="RichText__Container"] *,
  [class*="ExpandableContent"], [class*="SongInfo__Container"],
  [class*="Answer__Body"], [class*="Answer__Body"] *,
  [class*="EditorialPlacement__Dek"], [class*="SectionTitle__Subtitle"],
  [class*="ChartSong"], [class*="ChartSong"] *,
  [class*="RecommendedSong"] [class*="Title"],
  [class*="RecommendedSong"] [class*="Artist"] { color: #c4cdd6 !important; }

  /* The "Credits" block and the "Other Albums" cards render their labels, values and
     artist-name separators in plain <div>s the site paints black / black-60% — the
     shared typography list above only covers inline/text tags, so they stay
     black-on-dark and read as blank columns. */
  [class*="Credit__Contributor"], [class*="Credit__Contributor"] div,
  [class*="OtherAlbum__Info"], [class*="OtherAlbum__ArtistNames"] { color: #c4cdd6 !important; }
  [class*="Credit__Label"], [class*="SongTags__Title"] { color: #8b949e !important; }

  /* lyrics-header label row "<Song> Lyrics" sits right after the ⓘ info icon
     and is a non-link title the site paints near-black via -webkit-text-fill
     (defaults to currentColor) -> lift BOTH color and the webkit text-fill so it
     stays legible on the dark bar even if the site ships an !important fill */
  [class*="LyricsHeader__TitleContainer"], [class*="LyricsHeader__GroupContainer"],
  [class*="LyricsHeader__Title"], [class*="LyricsHeader__TitleContainer"] * {
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }

  /* ---- Links: keep the Genius periwinkle, lifted for dark contrast ---- */
  a, a span { color: #9aa7f0 !important; }
  a:hover { color: #c2cbff !important; }

  /* ====================================================================
     Action / UI icons (inline SVG) — black on the light site, invisible on
     dark. Lift the action-icon families to a legible light fill. The GENIUS
     wordmark, yellow IQ badges and brand-colored surfaces are handled
     elsewhere and are NOT in these families, so they stay intact.
     ==================================================================== */
  [class*="Button__Container"] svg, [class*="Button__Container"] svg path,
  [class*="ShareButtons__Container"] svg, [class*="ShareButtons__Container"] svg path,
  [class*="LyricsFooter"] svg, [class*="LyricsFooter"] svg path,
  [class*="VotingActions__Button"] svg, [class*="VotingActions__Button"] svg path,
  [class*="DropdownList__Icon"] svg, [class*="DropdownList__Icon"] svg path,
  [class*="Dropdown__Toggle"] svg, [class*="Dropdown__Toggle"] svg path,
  [class*="ContributorsCreditSong__Label"] svg, [class*="ContributorsCreditSong__Label"] svg path,
  [class*="InfoTooltip__Container"] svg, [class*="InfoTooltip__Container"] svg path,
  [class*="MetadataTooltip"] svg, [class*="MetadataTooltip"] svg path,
  [class*="LyricsHeader__Container"] svg, [class*="LyricsHeader__Container"] svg path,
  [class*="RoleIcon__Container"] svg, [class*="RoleIcon__Container"] svg path,
  [class*="InlineSvg__Wrapper"] svg, [class*="InlineSvg__Wrapper"] svg path {
    fill: #c4cdd6 !important; color: #c4cdd6 !important; }
  /* brand share glyphs (Facebook/Twitter) keep their own brand color, just
     ensure they're not pure-black-on-dark — lift to a light neutral too */
  [class*="ShareButtons__Container"] [aria-label*="Facebook"] svg path,
  [class*="ShareButtons__Container"] [aria-label*="Twitter"] svg path { fill: #c4cdd6 !important; }
  /* Verified-artist avatar (LyricsHeader byline / artist cards): the "verified" cue is a
     brand-yellow disc checkmark ("VerifiedInlineAvatar__CircleCheckMark": a yellow <circle>
     + a black <path> tick) plus a yellow ring on the avatar. The disc sits inside a
     "Button__Container", so the action-icon rule above greys the whole svg, and the blanket
     border reset greys the ring — the badge renders as a flat grey blob and the artist reads
     as unverified. Restore the yellow disc (the circle inherits the svg fill), keep the tick
     dark for contrast, and repaint the ring yellow. Scoped to the -Verified- class only. */
  [class*="VerifiedInlineAvatar__Container"] [class*="CircleCheckMark"] {
    fill: #ffff64 !important; }
  [class*="VerifiedInlineAvatar__Container"] [class*="CircleCheckMark"] path {
    fill: #14181d !important; }
  [class*="VerifiedInlineAvatar__Avatar"] { border-color: #ffff64 !important; }

  /* ====================================================================
     Lyrics body + annotations (referents)
     ==================================================================== */
  [data-lyrics-container],
  [class*="Lyrics__Container"],
  [class*="Lyrics__Root"] { color: #e6edf3 !important; background-color: transparent !important; }
  [data-lyrics-container] a { color: #e6edf3 !important; } /* inline section labels */

  /* Annotated (referent) words. The site paints the whole chip on the inner Highlight
     span and encodes its state ONLY in that span's background-color: #e9e9e9 at rest,
     pure BLACK while hovered OR while its annotation is open. Both are single-class
     styled-components rules whose hash changes every build, so no selector can name the
     open one — setting a background-color here flattens hover AND the "you are reading
     this one" cue into one identical chip across the whole song. Both site values are
     achromatic, so no single blend mode separates them either (luminosity maps both onto
     the layer's lightness, and every mode that keeps the resting chip dark maps black
     onto black). The three layers derive the two tones from that one value, bottom to
     top: `difference` against #e9e9e9 inverts it (rest -> 0, open -> 233), `multiply`
     tints the inverted value brand red, `lighten` floors it at the resting chip tone.
     Both source values are load-bearing — re-derive the stack if either changes. Do NOT
     add a background-color: the stack needs the site's own value underneath. */
  [class*="ReferentFragment-desktop__Highlight"],
  [class*="ReferentFragment"][class*="Highlight"] {
    background-image: linear-gradient(#21262d, #21262d),
                      linear-gradient(#6a2b24, #6a2b24),
                      linear-gradient(#e9e9e9, #e9e9e9) !important;
    background-blend-mode: lighten, multiply, difference !important;
    color: #e6edf3 !important; }
  /* the ClickTarget anchor around it is natively bare; painting it draws an elevated
     rectangle in the chip's padding that the blended span no longer matches */
  [class*="ReferentFragment-desktop__ClickTarget"] {
    background-color: transparent !important; color: #e6edf3 !important; }
  /* legacy "--active" referent (snarly pages): brand-red left accent */
  [class*="Referent"][class*="--active"] {
    background-color: #21262d !important; box-shadow: inset 3px 0 0 #ed4337 !important; }
  /* the open-annotation callout caret (the diamond pointing from the lyric to the
     annotation panel) is a rotated ::before square painted pure white with a light
     two-tone border -> match the dark panel surface so it reads as a subtle pointer */
  [class*="AnnotationPortal-desktop__Callout"]::before,
  [class*="AnnotationPortal"][class*="Callout"]::before {
    background-color: #14181d !important; border-color: #2d333b !important; }

  /* ---- Right sidebar / annotation panel ---- */
  [class*="RightSidebar__Container"],
  [class*="Sidebar__Container"],
  [class*="LyricsSidebarAd"] { background-color: transparent !important; }
  [class*="RecommendedSong__Container"],
  [class*="RecommendedSongs__Container"] { background-color: transparent !important; }
  [class*="RecommendedSong__Container"]:hover { background-color: #1c2128 !important; }
  /* annotation attribution "<N> contributors": a <button> (not <a>, so the link rule
     misses it) the site paints pure black via -webkit-text-fill-color — invisible on
     the dark annotation panel for the active/open annotation. Lift to the link tone. */
  [class*="Attribution__Container"] [class*="TextButton"],
  [class*="Attribution__Container"] [class*="TextButton"] * {
    color: #9aa7f0 !important; -webkit-text-fill-color: #9aa7f0 !important; }

  /* ====================================================================
     Cards / panels that default to white
     ==================================================================== */
  [class*="QuestionTemplate__Title"],
  [class*="MetadataQuestionTemplate__Title"],
  [class*="QuestionList__Table"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  /* Q&A question rows are brand-red on the live site and their expand/collapse glyph keeps
     that red, so flattening the title to plain light text leaves a red glyph beside a grey
     heading and drops the cue that the row opens. Restore the red, lifted to clear 4.5:1 on
     the card. Anchored with [class^=] because the substring above also matches
     "MetadataQuestionTemplate__Title", which the site paints black and must stay light. */
  [class^="QuestionTemplate__Title"],
  [class^="QuestionTemplate__Title"] *,
  [class^="QuestionTemplate__Container"] [class*="ExpandButton"],
  [class^="QuestionTemplate__Container"] [class*="ExpandButton"] svg,
  [class^="QuestionTemplate__Container"] [class*="ExpandButton"] path {
    color: #f26659 !important; fill: #f26659 !important;
    -webkit-text-fill-color: #f26659 !important; }
  /* The metadata Q&A rows ("Who produced …?") are an <a> wrapping a "__QuestionBody" span.
     The site paints the whole row its plain body black — it is an accordion heading, not a
     hyperlink — but the shared "a span" rule repaints the span periwinkle, so the row reads
     as an inline link and no longer matches the community Q&A titles it sits under. Return
     the descendants to the heading tone; the <a> itself is already covered above. */
  [class*="MetadataQuestionTemplate__Title"] * { color: #e6edf3 !important; }
  [class*="QuestionTemplate__Container"],
  [class*="MetadataQuestionTemplate__Container"],
  [class*="Answer__Container"],
  [class*="Comments__Container"],
  [class*="SongCommentsWithAds__Container"],
  [class*="SongDescription__Container"],
  [class*="About__Container"],
  [class*="MusicVideo__Container"],
  [class*="PrimaryAlbum__Container"],
  [class*="AlbumTracklist__Container"] {
    background-color: transparent !important; color: #c4cdd6 !important; }
  [class*="CommentForm__FakeTextField"] {
    background-color: #1c2128 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }
  /* "SongCommentsWithAds__CTA" and its "__CTASubHeading" sibling are the sign-up prompt's
     heading and paragraph, not a card — genius leaves both bare, so a surface here draws a
     grey slab hugging each block of copy. Colour only. */
  [class*="SongCommentsWithAds__CTA"] { color: #c4cdd6 !important; }
  /* Vote score ("+661" between the thumbs, on comments / annotations / Q&A answers): the
     site marks every running total with its own "background.<sign>Number" token attribute
     and paints the positive one green (#24c609) — the same sentiment cue the legacy
     ".voting-total--positive" rule restores on album/artist pages. The blanket
     "VotingActions__Button" colour flattens them all to plain light grey, so the modern
     song page loses a signal its legacy twin keeps. Key on the token itself, not on a
     component scope: the open-annotation total in the sidebar is green while the in-flow
     song-bio and Q&A totals resolve to WHITE (invisible on the site's own white card), so
     a scope narrower than the attribute restores the cue on one and drops it on the rest.
     The compound "VotingActions" form is required, not redundant: the neutral
     [class*="VotingActions__Button"] surface further down this file is the same 0-1-0
     specificity and comes LATER, so the bare attribute loses `color` to it and only the
     -webkit-text-fill-color survives — which paints in Chromium but not in Firefox. */
  [color="background.positiveNumber"], [color="background.positiveNumber"] *,
  [class*="VotingActions"][color="background.positiveNumber"] {
    color: #3fb950 !important; -webkit-text-fill-color: #3fb950 !important; }
  [color="background.negativeNumber"], [color="background.negativeNumber"] *,
  [class*="VotingActions"][color="background.negativeNumber"] {
    color: #f85149 !important; -webkit-text-fill-color: #f85149 !important; }
  /* "This song bio is unreviewed" banner (SongDescription / annotation): the site flags
     pending content with a white + light-pink candy-stripe background, a pink border and a
     pink "unreviewed" explainer toggle. The stripe's white bands glare as a light slab on
     the dark page, and the blanket border reset + the shared span rule grey out the pink
     border and the toggle, erasing the pending signal. Re-stripe on the dark base with a
     faint pink tint and restore the pink accent (lifted to clear 4.5:1). */
  [class*="UnreviewedAnnotation__Unreviewed"] {
    background-image: repeating-linear-gradient(45deg, #14181d, #14181d 7px, #2a1a22 7px, #2a1a22 14px) !important;
    border-color: #ff3d7f !important; }
  [class*="UnreviewedAnnotation__Unreviewed"],
  [class*="UnreviewedAnnotation__Unreviewed"] * {
    color: #ff3d7f !important; -webkit-text-fill-color: #ff3d7f !important; }

  /* ---- Apple Music player strip / media ---- */
  [class*="AppleMusicPlayer"] { background-color: #1c2128 !important; }
  /* ...but "__PositioningContainer", "__PageGrid" and "MediaPlayersContainer__Container" are
     the full-width LAYOUT wrappers around the 940px player, natively transparent (the grid is
     even pointer-events:none). Painting them draws an elevated band pinned across the bottom
     of the viewport, bleeding 170px past the player on each side. The PositioningContainer
     is the one that paints: it is fixed and 80px tall against the player's 64px, so it also
     frames the strip along the bottom edge. Only the IframeContainer is a real surface. */
  [class*="AppleMusicPlayer-desktop__PositioningContainer"],
  [class*="AppleMusicPlayer-mobile__PositioningContainer"],
  [class*="AppleMusicPlayer-desktop__PageGrid"],
  [class*="AppleMusicPlayer-mobile__PageGrid"],
  [class*="MediaPlayersContainer__Container"] { background-color: transparent !important; }
  /* The actual player UI renders in a same-origin genius.com/songs/<id>/apple_music_player
     iframe, so domain("genius.com") matches inside it. Its container/player/popup paint
     pure white by default -> dark; the divider is pure black -> soften to a dark line. */
  .apple_music_player-container, .apple_music_player-player,
  .apple_music_player-player-popup { background-color: #1c2128 !important; }
  .apple_music_player-divider { background-color: #2d333b !important; }
  /* Seekbar chrome is drawn for a WHITE player: the track is a pure-black ::before bar
     (invisible to element-bg scans) and the scrubber knob is a pure-black disc, both
     black-on-dark once the strip is themed. The Apple Music wordmark path is black too. */
  .apple_music_player-seekbar::before { background-color: #4a525c !important; }
  .apple_music_player-seekbar-scrubber-circle { background-color: #e6edf3 !important; }
  .apple_music_player-logo path,
  .apple_music_player-expanded_header-logo path { fill: #c4cdd6 !important; }
  /* "Featured Videos" module (artist/album pages) is a same-origin Primis video player
     served in a genius.com iframe. Our body rule darkens its document, but the inner
     #largeUnit slate stays pure white and frames the video with glaring white bands
     (the header label row + the gap above the thumbnail strip) -> darken the slate. */
  #largeUnit, .Large-unit, [class*="primis"] #largeUnit { background-color: #14181d !important; }

  /* ---- Tags / chips ---- */
  [class*="SongTags__Tag"], [class*="SquareManySelects__Container"],
  [class*="SquareSelectTitle__Container"], [class*="SquareManySelects__Select"] {
    background-color: #1c2128 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }
  [class*="SongTags__Tag"]:hover { background-color: #2d333b !important; }
  /* "SongTags__TagContainer" is the transparent flex wrapper AROUND the chips, not a chip;
     the substring above swallows it and paints a grey slab behind the whole tag row. */
  [class*="SongTags__TagContainer"] { background-color: transparent !important; }
  /* The chart selector (home / charts) carries two inline SVGs that ship no fill attribute,
     so they default to black — drawn for the white panel, invisible on the dark one. The
     tick is the ONLY marker of which type / genre / period is selected, so it is lifted
     brighter than the open/close chevron beside it. */
  [class*="SquareSelectTitle__Arrow"] svg,
  [class*="SquareSelectTitle__Arrow"] svg path {
    fill: #c4cdd6 !important; }
  [class*="SquareSelectOption__Container"] svg,
  [class*="SquareSelectOption__Container"] svg path {
    fill: #e6edf3 !important; }

  /* ---- Buttons ---- */
  [class*="Button__Container"], [class*="VotingActions__Button"],
  [class*="ExpandableContent__Button"], [class*="List__More"],
  [class*="SquareButton"], [class*="Charts__LoadMore"] button {
    background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  /* The "*__LoadMore" and "ExpandableContent__ButtonContainer" classes sit on the
     full-width GRID WRAPPER around the button, not on the button — giving them the
     button surface paints a long grey slab behind (and level with) the button. They
     are transparent on the live site; keep them that way. */
  [class*="Charts__LoadMore"], [class*="Latest-desktop__LoadMore"],
  [class*="Community-desktop__LoadMore"], [class*="Videos-desktop__LoadMore"],
  [class*="ExpandableContent__ButtonContainer"] {
    background-color: transparent !important; }
  [class*="SquareButton"] *, [class*="Charts__LoadMore"] * { color: #e6edf3 !important; }
  /* "VotingActions__Button" is not a button surface: genius ships it with no fill and no
     edge at all (border-width 0), because it is the bare thumb / running-total row that sits
     inline in the annotation, comment and Q&A copy. The neutral surface above boxes each
     glyph, and the running total — the one item wide enough to show it — ends up a lighter
     chip that reads as pressed. Same opt-out the legacy ".square_button--transparent" twin
     already gets; the hover below still answers the pointer. */
  [class*="VotingActions__Button"] { background-color: transparent !important; }
  /* "SquareButton" is the outline CTA of the React shell ("Load More", "Join Our Community",
     "Show more songs"): the site gives it no resting fill and its whole affordance is a hover
     that inverts to a solid #000 or #fff. The resting surface below is !important, so that
     inversion cannot land — the family must be named here or it never answers the pointer. */
  [class*="Button__Container"]:hover, [class*="VotingActions__Button"]:hover,
  [class*="SquareButton"]:hover {
    background-color: #2d333b !important; }
  /* dropdown pointer: an 11px square rotated 45deg, painted pure white */
  [class*="DropdownList__Caret"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="DropdownList__ItemsContainer"], [class*="Dropdown__ContentContainer"],
  [class*="DropdownList__Item"], [class*="DropdownList__LabeledButton"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  [class*="DropdownList__Item"]:hover { background-color: #2d333b !important; }

  /* ---- Hover tooltips (artist cards, the ⓘ metadata popup) ----
     "PortalTooltip__Container" / "InfoTooltip__Container" / "MetadataTooltip__InfoTooltip"
     are the inline TRIGGER wrappers (a 12x21 icon box, an 88x16 credit name), natively
     transparent — painting them draws a lighter rectangle behind every contributor name
     and every ⓘ. The floating panel is a separate portal node, "TooltipShadow". */
  [class*="PortalTooltip__Container"], [class*="InfoTooltip__Container"],
  [class*="MetadataTooltip__InfoTooltip"], [class*="LyricsHeader__MetadataTooltip"] {
    background-color: transparent !important; }
  /* The panel ships pure white for a normal artist and brand-yellow for a verified one —
     both keep black text, so our lifted light text lands unreadable on them. The two
     variants differ only by a build-volatile styled-components hash, so darken both and
     carry the verified signal on its own stable "Verified" eyebrow, in the brand yellow. */
  [class*="TooltipShadow"] {
    background-color: #1c2128 !important; background-image: none !important;
    border-color: #2d333b !important; }
  [class*="ArtistTooltip__Container"], [class*="ArtistTooltip__Container"] * {
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }
  [class*="ArtistTooltip__ArtistTooltipName"] {
    color: #9aa7f0 !important; -webkit-text-fill-color: #9aa7f0 !important; }
  [class*="ArtistTooltip__Verified"] {
    color: #ffff64 !important; -webkit-text-fill-color: #ffff64 !important; }
  /* The ⓘ lyrics-metadata popup is a Radix popover ("TooltipContent" with its own
     "TooltipArrow" div), NOT the "TooltipShadow" panel the artist card uses: it ships a
     pure-white card with a white arrow and black line rows, so our lifted light text
     lands on white and the whole popup reads blank. It only exists while the ⓘ is
     hovered, so no load-time scan sees it. Darken panel + arrow and lift the rows. */
  [class*="TooltipContent"] {
    background-color: #1c2128 !important; background-image: none !important;
    border-color: #2d333b !important; }
  [class*="TooltipArrow"] { background-color: #1c2128 !important; }
  [class*="InfoTooltip__InfoTooltipLine"],
  [class*="InfoTooltip__LineText"] { color: #c4cdd6 !important; }

  /* ====================================================================
     Homepage modules
     ==================================================================== */
  [class*="HomeContent-desktop__Section"],
  [class*="HomeContent-desktop__Container"],
  [class*="HomeContent"] { background-color: transparent !important; }
  [class*="ChartItem-desktop__Row"], [class*="ChartItem"][class*="Row"],
  [class*="EditorialPlacement__Container"], [class*="TopContent-desktop__Placement"],
  [class*="Latest-desktop__Placement"], [class*="Videos-desktop__Hero"],
  [class*="CommunityRanking-desktop__Row"], [class*="Community-desktop__User"] {
    background-color: transparent !important; }
  /* Both row families carry the same #e9e9e9 hover fill in the site's sheet; the community
     leaderboard has to be named beside the chart rows or only one of the two answers the
     pointer once the transparent-neutralizer above has run. */
  [class*="ChartItem-desktop__Row"]:hover, [class*="EditorialPlacement__Container"]:hover,
  [class*="CommunityRanking-desktop__Row"]:hover {
    background-color: #1c2128 !important; }
  [class*="ChartSong-desktop__Title"], [class*="EditorialPlacement__Title"] { color: #e6edf3 !important; }
  /* Homepage news cards repeat the article-link underline-skip trick on hover: a black
     1px background-image "underline" plus a WHITE text-shadow halo (out to .15em) that
     punches gaps around the glyphs so the rule skips descenders. On the dark card the
     black underline vanishes and the fat white halo floods the letters into a blob.
     Re-point the halo at the hovered card surface and the underline at the title tone.
     Keeping the halo (rather than dropping it) preserves the descender skip.
     The size/repeat/position MUST be restated: only the DESKTOP bundle ships them, so on
     the mobile bundle the bare gradient inherits `auto`/`repeat` and floods the whole
     title box with a solid light slab the moment the card is touched or hovered. */
  [class*="EditorialPlacement__Link"]:hover [class*="EditorialPlacement__Title"] h2,
  [class*="EditorialPlacement__Link"]:hover [class*="EditorialPlacement__Title"] h3 {
    color: #e6edf3 !important;
    background-image: linear-gradient(#e6edf3, #e6edf3) !important;
    background-size: 100% 1px !important;
    background-repeat: no-repeat !important;
    background-position: 0 100% !important;
    text-shadow: 0.03em 0 #1c2128, -0.03em 0 #1c2128, 0 0.03em #1c2128, 0 -0.03em #1c2128,
                 0.06em 0 #1c2128, -0.06em 0 #1c2128, 0.09em 0 #1c2128, -0.09em 0 #1c2128,
                 0.12em 0 #1c2128, -0.12em 0 #1c2128, 0.15em 0 #1c2128, -0.15em 0 #1c2128 !important; }
  [class*="ChartSong-desktop__Artist"], [class*="EditorialPlacement__Author"],
  [class*="EditorialPlacement__PublishedAt"], [class*="ChartSong-desktop__Metadatum"] { color: #8b949e !important; }
  /* red eyebrow label ("NEWS" / "FEATURE" / "VIDEO") — the word sits in a <span> inside the
     card's <a>, so the generic "a span" link rule repaints it periwinkle unless the
     descendant is named too. Lifted from the raw brand #ed4337: that clears 4.5:1 on the
     #14181d base but only reaches 4.21:1 once the card is HOVERED, because the hover rule
     below raises the card to #1c2128 — measure the eyebrow against the surface it actually
     lands on, not the page floor. #f26659 is the same brand red the Q&A titles use and
     holds 5.3:1 on the hovered card. */
  [class*="EditorialPlacement__Label"],
  [class*="EditorialPlacement__Label"] * { color: #f26659 !important; }
  [class*="UserBadge__Name"] { color: #c4cdd6 !important; }
  [class*="UserBadge__Role"], [class*="Community-desktop__Iq"], [class*="CommunityRanking-desktop__Iq"] { color: #8b949e !important; }
  /* Section eyebrows ("MOST RECENT NEWS", "GENIUS ORIGINAL SERIES") and the community
     leaderboard's IQ scores are the site's accent colour, carried on a stable
     color="accent.main" attribute (the value itself lives on a build-volatile
     styled-components hash). The blanket h1-h6 rule greys the eyebrows and the "a span"
     link rule repaints the IQ scores periwinkle, so the accent is lost either way.
     Accent is section-scoped: brand pink everywhere, brand yellow in the Videos band
     (#videos). The pink is lifted from #ff1464 (4.4:1) to clear 4.5:1 on the base. */
  [class*="HomeContent"] [color="accent.main"],
  [class*="HomeContent"] [color="accent.main"] * {
    color: #ff3d7f !important; -webkit-text-fill-color: #ff3d7f !important; }
  #videos [color="accent.main"], #videos [color="accent.main"] * {
    color: #ffff64 !important; -webkit-text-fill-color: #ffff64 !important; }

  /* ====================================================================
     LEGACY ("snarly") pages — artist + search results
     ==================================================================== */
  /* legacy top nav */
  .header, .header-inner, .header_nav, .header_with_login {
    background-color: #0d1117 !important; border-bottom: 2px solid #ed4337 !important; color: #e6edf3 !important; }
  .header a, .header_nav a, .header_nav-menu_item, .logo_link { color: #e6edf3 !important; }
  .header a:hover { color: #ffffff !important; }
  /* legacy GENIUS wordmark is a dark raster sprite in ::before -> invert to light */
  .logo_link::before, .header_logo::before, a.logo::before {
    filter: invert(1) brightness(1.9) !important; }
  .logo_link, .header_logo { color: #e6edf3 !important; }
  .header_search-input, input.header_search-input, .search_input {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .header_search-input::placeholder { color: #8b949e !important; }

  /* containers / cards. ".mini_card" is excluded on its own "--transparent" modifier:
     genius ships ".mini_card--transparent{background-color:transparent}" and the base
     fill here outranked it, so the artist page's Top Songs list rendered as a stack of
     elevated panels instead of the flat list the site draws. ".user_badge" is NOT a card
     — in genius's sheet it is a bare flex row with no background at all; filling it drew
     a lighter chip hugging the avatar+name of every leaderboard entry and stopping dead
     mid-row. ".leaderboard" is likewise bare (position/z-index/font only): it is the
     contributor leaderboard, NOT an ad slot, and it always sits inside a ".white_container",
     so any fill of its own cuts a differently-toned rectangle out of that card. */
  .white_container, .mini_card:not(.mini_card--transparent), .mini_article_card, .thumbnail_grid,
  .standalone_annotation, .song_card, .full_width_container--white,
  .horizontal_album_card, .feed_item, .annotation_sidebar_unit,
  .article_card, .text_card, .cosign_unit,
  .profile_contribution, .full_width_link, .full_width_card, .grid_video {
    background-color: #1c2128 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }
  /* ".vertical_album_card" is not a card either: bagon gives it colour and padding only and
     puts its whole state vocabulary in a fill — #e9e9e9 while hovered, the same tone plus a
     .5rem ring for the "--active" album. A resting surface here outranks both, so the album
     grid stops answering the pointer and the current album goes unmarked. Keep the tile bare
     and restate each state on the dark scale. */
  .vertical_album_card { background-color: transparent !important; color: #c4cdd6 !important; }
  .vertical_album_card:hover { background-color: #21262d !important; }
  .vertical_album_card--active {
    background-color: #21262d !important; box-shadow: 0 0 0 0.5rem #21262d !important; }
  .full_width_link, .full_width_link * { color: #c4cdd6 !important; }
  /* legacy "gray_container" (album/article comment boxes, the ellipsis menu, the
     bottom strip) paints rgba(204,204,204,.2) — a translucent light wash that turns
     into a washed-out grey slab over the dark base. Make it a normal dark card.
     ".profile_preview" (the MOBILE artist-page description teaser) uses the very same
     translucent wash and keeps its own #222 body copy, so the teaser reads dark-on-
     light-grey; darken the card and lift the rows, keeping the contributor link blue. */
  .gray_container, .comments.gray_container, .ellipsis_menu.gray_container,
  .profile_preview {
    background-color: #1c2128 !important; }
  .profile_preview-row, .profile_preview-rows { color: #c4cdd6 !important; }
  .profile_preview-row a { color: #9aa7f0 !important; }
  /* genius gates its own hover fill the same way (".mini_card:not(.mini_card--transparent):hover") */
  .mini_card:not(.mini_card--transparent):hover,
  .mini_article_card:hover, .song_card:hover { background-color: #21262d !important; }
  .full_width_container { background-color: transparent !important; }
  /* Album-tracklist / chart rows draw their divider on a full-bleed ::before carrying a
     near-white border. The blanket border reset at the top of the file is `*`, which does
     NOT match pseudo-elements, so that line survives and paints a bright bar across the
     whole left gutter beside every dark row divider. */
  .chart_row::before, .chart_row::after { border-color: #262c33 !important; }
  /* legacy 404 / error page: the render_404 panel keeps a pure-white background while
     our typography rules already lift its headline + copy to light -> light-on-white =
     invisible title. Darken the panel so the error text reads. */
  .render_404, [class*="render_404"] { background-color: #14181d !important; }
  /* the 404 "sgnarly" mascot is a black-on-white raster GIF that renders as a glaring
     white square on the dark error page -> invert so it reads as a light mascot on dark.
     Inverting turns the GIF's white ground pure black, which is a visible square against
     #14181d; "lighten" then lets the (lighter) page show through the black ground while
     the now-white mascot still wins per channel. */
  .render_404-image, img.render_404-image {
    filter: invert(1) !important; mix-blend-mode: lighten !important; }

  /* legacy editorial article / news page (<article-page>): the .grid_layout content
     wrapper inside the dark .white_container stays pure-white, and the byline/share
     "info_and_action_box" panels are white too -> dark so the body copy (already
     lifted to light) is readable. The article title uses an "outline" variant with a
     black -webkit-text-stroke for legibility over the hero image; on the dark body it
     would render as black-outlined light text -> drop the black stroke so it reads. */
  article-page .grid_layout { background-color: transparent !important; }
  .article_info_and_action_box {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* the .article_rich_text_formatting body wrapper sets its OWN #333 text color, which
     the inline emphasis tags the shared typography list omits (<center>, <strong>, <b>,
     legacy <font>) inherit -> dark-on-dark intro/lead lines on the dark article card.
     Lift the wrapper to the readable body tone; inline links keep their periwinkle rule. */
  .article_rich_text_formatting, .article_rich_text_formatting center,
  .article_rich_text_formatting strong, .article_rich_text_formatting b,
  .article_rich_text_formatting font {
    color: #c4cdd6 !important; }
  .article_title, .article_title--o {
    -webkit-text-stroke: 0 !important; color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }
  /* article body + sidebar reference links fake an underline-skip: a black 1px
     background-image "underline" plus a WHITE text-shadow halo punched around each
     glyph. On dark the underline vanishes and the white halo outlines every letter,
     so the links read as double-struck. Re-point both at the card surface / link hue.
     The size/repeat/position MUST be restated: only the desktop article stylesheet
     ships them, so on the AMP mobile article (same .article_rich_text_formatting
     wrapper, no underline trick) the bare gradient inherits `auto`/`repeat` and fills
     the whole link box with a solid periwinkle block. */
  .article_reference_link, .article_rich_text_formatting a {
    background-image: linear-gradient(#9aa7f0, #9aa7f0) !important;
    background-size: 100% 1px !important;
    background-repeat: no-repeat !important;
    background-position: 0 100% !important;
    text-shadow: 0.84px 0 0 #1c2128, -0.84px 0 0 #1c2128,
                 1.68px 0 0 #1c2128, -1.68px 0 0 #1c2128 !important; }

  /* legacy text colors (#222 / #444) -> light */
  .mini_card-title, .mini_article_card-title, .song_card-title,
  .vertical_album_card-album_name, .text_label, .profile_identity-name,
  .list_section-header_label, .metadata_unit-info, .header_with_cover_art-primary_info_title {
    color: #e6edf3 !important; }
  .mini_card-subtitle, .mini_article_card-subtitle, .song_card-info,
  .vertical_album_card-artist_name, .metadata_unit-label, .text_2, .small_text,
  .u-quarter_top_margin, .secondary_info { color: #c4cdd6 !important; }
  .mini_card_grid-title, .list_section .text_label { color: #e6edf3 !important; }
  /* "More on Genius" recirculated article cards: titles ship near-black (#222) and
     vanish on dark -> lift; the date/meta line to the muted secondary tone */
  .recirculated_content-title { color: #e6edf3 !important; }
  .recirculated_content-subtitle, .recirculated_content-date,
  .recirculated_content-author { color: #c4cdd6 !important; }

  /* legacy profile header is already dark — keep it, just soften */
  .profile_header { background-color: #0d1117 !important; }
  /* "u-white_background" is the site's own paint-it-white utility. On the MOBILE artist
     page the profile tab strip carries it, so a 390x38 white band sits between the Q&A
     block and the activity feed with its tab label (lifted light by our typography)
     invisible on it. The desktop tab strip inherits the dark profile header instead, so
     the strip only appears on the mobile bundle. Darken the utility itself. */
  .u-white_background, .profile_tabs.u-white_background {
    background-color: #14181d !important; }
  /* the annotation body's loading skeleton paints pure white behind the placeholder
     lines; it is only opacity:0 once loaded, so it flashes as a full-height white slab */
  .annotation_placeholder, .placeholder.annotation_placeholder {
    background-color: #1c2128 !important; }
  .profile_tabs-tab--selected { border-bottom-color: #ed4337 !important; color: #ffffff !important; }
  /* The blanket border reset above repaints EVERY border, including the ones the site
     uses as accents rather than as dividers: the coloured 2px underline that marks a
     "text_label--<colour>" link-button, and the ring around the profile avatar.
     The avatar ring is NOT decorative: the site paints it BRAND YELLOW for a VERIFIED
     artist (.profile_header-avatar--verified, #ffff64 in bagon_desktop.css) and white
     otherwise, so pinning every ring to white erased the verified signal. Restore the
     ring per state, in the site's own yellow — the same hue every other verified cue
     uses (the VerifiedInlineAvatar disc, the artist-tooltip "Verified" eyebrow). */
  .profile_header-avatar { border-color: #e6edf3 !important; }
  .profile_header-avatar--verified { border-color: #ffff64 !important; }

  /* Legacy semantic label colours. ".text_label" sits in the light-text list above, so
     EVERY colour variant the site ships (pink / verified / green / red / yellow /
     purple / gray / white — enumerated from bagon_desktop.css) was flattened to one
     grey: the verified-annotations CTA, the "See All" alternate-names link, the pink
     tab counts. Restore each, and the matching --button underline with it. Pink is
     lifted from #ff1464 (4.4:1) and red from #ff1414 (4.3:1) to clear 4.5:1 on dark.
     "--verified" is the brand YELLOW #ffff64 in bagon_desktop.css, NOT a green — it is
     the same token as "--yellow", and painting it green invents a hue the site never uses. */
  .text_label.text_label--pink, .text_label.text_label--pink *,
  .profile_tabs-tab-count, .profile_identity-alternate_names-see_all {
    color: #ff3d7f !important; }
  .text_label.text_label--pink { border-bottom-color: #ff3d7f !important; }
  .text_label.text_label--red, .text_label.text_label--red * { color: #ff4d4d !important; }
  .text_label.text_label--red { border-bottom-color: #ff4d4d !important; }
  .text_label.text_label--verified, .text_label.text_label--verified * { color: #ffff64 !important; }
  .text_label.text_label--verified { border-bottom-color: #ffff64 !important; }
  .text_label.text_label--green, .text_label.text_label--green * { color: #0ecb27 !important; }
  .text_label.text_label--green { border-bottom-color: #0ecb27 !important; }
  .text_label.text_label--yellow, .text_label.text_label--yellow * { color: #ffff64 !important; }
  .text_label.text_label--yellow { border-bottom-color: #ffff64 !important; }
  .text_label.text_label--purple, .text_label.text_label--purple * { color: #9aa7f0 !important; }
  .text_label.text_label--purple { border-bottom-color: #9aa7f0 !important; }
  .text_label.text_label--gray, .text_label.text_label--gray * { color: #9a9a9a !important; }
  .text_label.text_label--gray { border-bottom-color: #9a9a9a !important; }
  /* annotation "Read More" affordance ships the periwinkle link hue; the shared span
     rule greys it, so it stops reading as clickable */
  .truncated_annotation_text-read_more { color: #9aa7f0 !important; }
  /* contributor leaderboard: the rank, the username and the IQ score are the periwinkle
     accent, greyed by the shared span rule — the column reads as plain metadata without it */
  .leaderboard-rank, .leaderboard-rank *,
  .leaderboard-sort_value, .leaderboard-sort_value *,
  .leaderboard-user, .leaderboard-user *,
  .header_with_cover_art-pyongs_count { color: #9aa7f0 !important; }
  /* the filled count pills carry a 2px border in their OWN fill colour (so each reads as a
     solid pill); the blanket border reset draws a dark ring around them. genius ships four
     variants and they must all be restated or the ring comes back on the ones left out:
     "--purple_filled" #99a7ee, "--pink_filled" #ff1464, and the unfilled "--gray" / "--red"
     whose edge IS the pill (they have no background at all). Red is lifted from the site's
     #ff1414 (4.3:1) to clear 4.5:1 on the dark card. */
  .numbered_indicator--purple_filled { border-color: #99a7ee !important; }
  .numbered_indicator--pink_filled { border-color: #ff1464 !important; }
  .numbered_indicator--gray { border-color: #9a9a9a !important; color: #9a9a9a !important; }
  .numbered_indicator--red { border-color: #ff4d4d !important; color: #ff4d4d !important; }

  /* legacy buttons / tags */
  .normal_button, .text_button, .quinary_button, .tag,
  .square_button, .full_width_button {
    background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .normal_button:hover, .text_button:hover, .square_button:hover, .full_width_button:hover { background-color: #2d333b !important; }
  .tag:hover { background-color: #2d333b !important; }
  .square_button *, .full_width_button * { color: #e6edf3 !important; }
  /* Brand share / artist-social buttons. The neutral ".square_button" surface above has
     the same specificity and comes first, so it SWALLOWED every brand fill the site
     ships (facebook/twitter/instagram/google/spotify/apple/email) and the buttons all
     rendered as identical grey boxes — the earlier "keeps their brand bg" comment was
     simply wrong. Re-assert each brand fill with a two-class selector so it wins.
     Instagram/Apple are brand-black: keep the fill but give them a visible edge, or the
     button reads as a hole punched in the dark page. */
  .square_button.square_button--facebook { background-color: #3b5998 !important; border-color: #3b5998 !important; }
  .square_button.square_button--twitter { background-color: #55acee !important; border-color: #55acee !important; }
  .square_button.square_button--google { background-color: #dd4b39 !important; border-color: #dd4b39 !important; }
  .square_button.square_button--spotify { background-color: #2ebd59 !important; border-color: #2ebd59 !important; }
  .square_button.square_button--email { background-color: #9a9a9a !important; border-color: #9a9a9a !important; }
  .square_button.square_button--instagram,
  .square_button.square_button--apple { background-color: #000000 !important; border-color: #2d333b !important; }
  /* Each brand fill above sits at the same specificity as (and after) the neutral
     ".square_button:hover", so that hover cannot reach these buttons and each variant needs
     its own. Genius lightens the fill by 20% on hover; carry that through. */
  .square_button.square_button--facebook:hover { background-color: #4c70ba !important; border-color: #4c70ba !important; }
  .square_button.square_button--twitter:hover { background-color: #83c3f3 !important; border-color: #83c3f3 !important; }
  .square_button.square_button--google:hover { background-color: #e47265 !important; border-color: #e47265 !important; }
  .square_button.square_button--instagram:hover { background-color: #4d4d4d !important; }
  .square_button.square_button--apple:hover { background-color: #1a1a1a !important; }
  .square_button.square_button--email:hover { background-color: #b4b4b4 !important; border-color: #b4b4b4 !important; }
  /* "--transparent" is genius's opt-out of the family's chrome ("background:0 0;
     border-color:transparent") and it is what the vote thumbs, their running total and the
     comment/share actions all carry. The neutral surface is one class less specific but both
     its fill and its edge still land, so the opt-out has to be restated here — otherwise every
     bare glyph renders as a boxed cell and the row reads as a segmented control. */
  .square_button.square_button--transparent {
    background-color: transparent !important; border-color: transparent !important; }
  .square_button.square_button--transparent:hover { background-color: #2d333b !important; }
  .square_button--facebook, .square_button--twitter, .square_button--google,
  .square_button--instagram, .square_button--spotify, .square_button--apple, .square_button--email {
    color: #ffffff !important; }
  /* the "--purple" variant is an accent icon button (the annotation/contribution expand
     caret): the site carries the periwinkle in its glyph, which the neutral .square_button
     rule above flattens to the same light grey as every other button */
  .square_button.square_button--purple,
  .square_button.square_button--purple * { color: #9aa7f0 !important; fill: #9aa7f0 !important; }
  /* The rest of the ".square_button" family is not a fill family at all: bagon_desktop.css
     draws it as an OUTLINE control (transparent background, `border-color` + `color` +
     `.inline_icon{fill}` all set to one hue) and puts the whole meaning in that hue —
     #ff1414 destructive, #0ecb27 the affirmative "Submit", #ffff64 / #fff emphasis,
     #9a9a9a muted and the "--waiting" in-flight state. The neutral surface rule above is
     the same specificity and comes first, so every variant collapses into one identical
     grey box and the family stops telling destructive from affirmative. Re-assert each
     hue on the edge, the label and the glyph with a two-class selector, lifted to clear
     4.5:1 on the #21262d fill (#ff1414 is only 3.8:1 there). Enumerated from
     bagon_desktop.css, same as the .text_label--* block below. */
  .square_button.square_button--red, .square_button.square_button--red *,
  .square_button.square_button--red .inline_icon {
    color: #ff4d4d !important; fill: #ff4d4d !important; border-color: #ff4d4d !important; }
  .square_button.square_button--green, .square_button.square_button--green *,
  .square_button.square_button--green .inline_icon {
    color: #0ecb27 !important; fill: #0ecb27 !important; border-color: #0ecb27 !important; }
  .square_button.square_button--yellow, .square_button.square_button--yellow *,
  .square_button.square_button--yellow .inline_icon {
    color: #ffff64 !important; fill: #ffff64 !important; border-color: #ffff64 !important; }
  .square_button.square_button--white, .square_button.square_button--white *,
  .square_button.square_button--white .inline_icon {
    color: #ffffff !important; fill: #ffffff !important; border-color: #ffffff !important; }
  /* "--gray" / "--waiting" / "--disabled" are the DE-emphasised end of the same family
     (genius draws the default variant with a black edge and these three with the same
     #9a9a9a one). Only the label and glyph move: pinning their edge to #9a9a9a too would
     make the muted variant louder than the default #2d333b edge and invert the hierarchy.
     "--disabled" carries no other cue than that hue — flattened to the default light
     label, a disabled control reads as enabled. */
  .square_button.square_button--gray, .square_button.square_button--gray *,
  .square_button.square_button--gray .inline_icon,
  .square_button.square_button--waiting, .square_button.square_button--waiting *,
  .square_button.square_button--waiting .inline_icon,
  .square_button.square_button--disabled, .square_button.square_button--disabled *,
  .square_button.square_button--disabled .inline_icon {
    color: #9a9a9a !important; fill: #9a9a9a !important; }
  /* The "_inverse" pair is the outline form of the two brand buttons: no fill, the brand
     hue on the label and the glyph only. The neutral family rule above is the same
     specificity and comes first, so both collapse into the plain light button. Facebook
     blue is lifted from #3b5998 (2.2:1 on the #21262d fill) to clear 4.5:1; Twitter's
     #55acee already clears it. */
  .square_button.square_button--facebook_inverse,
  .square_button.square_button--facebook_inverse *,
  .square_button.square_button--facebook_inverse .inline_icon {
    color: #8ba4e0 !important; fill: #8ba4e0 !important; }
  .square_button.square_button--twitter_inverse,
  .square_button.square_button--twitter_inverse *,
  .square_button.square_button--twitter_inverse .inline_icon {
    color: #55acee !important; fill: #55acee !important; }
  .square_button--facebook *, .square_button--twitter *, .square_button--google *,
  .square_button--instagram *, .square_button--spotify *, .square_button--apple *,
  .square_button--email * { color: #ffffff !important; }
  /* legacy inline action-button glyphs — the pyong (IQ lightning) button and the
     header search magnifier ship a pure-black SVG fill that vanishes on the dark
     surfaces. Lift them to a legible light neutral. The FB/Twitter share glyphs
     carry their own brand color and aren't in these families, so they stay intact. */
  .pyong_button svg, .pyong_button svg path,
  .global_search-submit_button svg, .global_search-submit_button svg path,
  .header_search-submit svg, .header_search-submit svg path {
    fill: #c4cdd6 !important; color: #c4cdd6 !important; }

  /* Genius IQ badges: keep the signature yellow fill, dark text for contrast.
     The fill belongs to "tag_label--yellow_background" and NOTHING else — in genius's
     own sheet ".user_badge-iq" carries no colour at all and ".profile_identity-iq" only
     a font-size. Keying the yellow on those bare classes invented a surface: the artist
     page's scholars leaderboard renders ".user_badge-iq--one_line" (transparent, #9a9a9a
     ink) and every row came out a loud yellow pill genius never paints. The genuinely
     yellow badges all carry the tag_label class too, so they stay covered. */
  .tag_label--yellow_background, [class*="tag_label--yellow"] {
    background-color: #ffff64 !important; color: #14181d !important; }
  .tag_label--yellow_background *, [class*="tag_label--yellow"] * { color: #14181d !important; }
  /* the unfilled IQ variant: keep the site's muted grey, legible on the dark card */
  .user_badge-iq--one_line:not(.tag_label--yellow_background),
  .user_badge-iq--one_line:not(.tag_label--yellow_background) * {
    background-color: transparent !important; color: #9a9a9a !important; }
  /* lazy-load skeleton paints the badge #ccc on #ccc */
  .placeholder .user_badge-iq, .placeholder .user_badge-login {
    background-color: #2d333b !important; color: #2d333b !important; }

  /* periwinkle count chips: keep accent bg, dark label for contrast */
  .profile_contributions_group-count, .profile_contributions_group-count * { color: #14181d !important; }

  /* legacy contribution vote score ("+1793" between the thumb buttons): the site paints
     it green when net-positive and red when negative — a real sentiment cue. It carries
     "square_button", so the neutral .square_button color rule above flattens both to grey
     and the up/down signal is lost. Restore it, lifted for contrast on the dark card. */
  .voting-total--positive, .voting-total--positive * { color: #3fb950 !important; }
  .voting-total--negative, .voting-total--negative * { color: #f85149 !important; }

  /* legacy active header tab: yellow underline -> brand red */
  .header-primary.active, .header_with_login .active {
    background-color: transparent !important; box-shadow: inset 0 -3px 0 #ed4337 !important; }

  /* legacy avatar / image placeholders */
  .user_avatar, .profile_header-avatar, .avatar { background-color: #1c2128 !important; }

  /* legacy "STATS" panel (charts / profile contributor pane): white card with black
     glyph icons + #666 labels -> dark card, light icons, legible labels */
  .statistics_panel { background-color: #1c2128 !important; border-color: #2d333b !important; }
  .statistics_panel svg, .statistics_panel svg path { fill: #c4cdd6 !important; }
  .statistic_and_label-number { color: #e6edf3 !important; }
  .statistic_and_label-subtext { color: #8b949e !important; }

  /* legacy dropdowns / menus */
  .dropdown_menu, .dropdown_menu-item, .menu {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .dropdown_menu-item:hover { background-color: #2d333b !important; }
  /* the legacy flyout menu (profile "All contributions", and the other docked menus) is a
     white .tooltip panel with black <div> rows — the shared typography list covers inline
     tags only, so it stays a glaring white card. It only exists once opened. */
  .tooltip { background-color: #1c2128 !important; border-color: #2d333b !important; }
  .tooltip-list_item, .tooltip-list_item * { color: #e6edf3 !important; }
  .tooltip-list_item:hover { background-color: #2d333b !important; }
  /* legacy search autocomplete: the feed_dropdown panel paints #f7f7f7 behind the
     result rows -> dark so the section-header bands stop flashing white */
  .feed_dropdown, .feed_dropdown--medium_width {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .feed_dropdown .section_header, .feed_dropdown-section_header,
  .feed_dropdown .text_label { color: #8b949e !important; }

  /* legacy lyric annotation highlight. Every colour variant the site ships
     (--green #ff9, --yellow, --red #ff7070, --gray, --white) paints the chip TWICE: a
     background-color AND a matching pair of 0.01em left/right box-shadows that extend the
     highlight past the inline box. Overriding only the background leaves those two shadows
     at their original pale-yellow, so each annotated lyric on an artist/legacy page ends up
     bracketed by a bright sliver at both ends. Drop them; the chip fill is the whole cue.
     ".referent--yellow" below restates its own shadow at higher specificity, so its brand-red
     accent still wins. */
  .referent, a.referent {
    background-color: #1c2128 !important; color: #e6edf3 !important; box-shadow: none !important; }
  /* ...and the STATE the fill encoded has to come back, or every annotation looks alike.
     genius keeps an annotation's state entirely in that background-color — #ff9 for
     "--green", #ff7070 for "--red" — and marks the one currently open by swapping it for a
     saturated "--highlighted" tone (#ffff64, or #ff1414 on a red one). The base rule above
     repaints all of them, so an artist page's contributions feed renders every annotated
     excerpt identically and the open one is unmarked: measured on /artists/Kendrick-lamar,
     three "--green" excerpts all resolving to the same #1c2128 as a plain referent.
     Re-tint the fill rather than draw an inset bar — ".referent" is display:inline with
     `padding:.2em 0`, i.e. NO horizontal padding, so an inset edge lands on top of the
     excerpt's first glyph instead of beside it. Each tone keeps the light copy above 9:1.
     ".referent--yellow" is deliberately NOT in this list: bagon_desktop.css ships no bare
     "--yellow" fill at all (only "--yellow.--highlighted"), so at rest it IS the base chip
     and giving it its own surface invented a distinction genius never draws. */
  .referent.referent--green { background-color: #1b2a1e !important; }
  .referent.referent--red { background-color: #2e1c1f !important; }
  .referent.referent--highlighted { background-color: #3d3d1a !important; }
  .referent.referent--red.referent--highlighted { background-color: #4a1e1e !important; }
  /* The excerpt WRAPPER has the same three states as a full-bleed panel
     ("referent_container--inverse" / "--green" #ffff64, "--red" #ff1414) plus a
     scroll-fade ::before that ramps to the same colour. Nothing in this file matched them,
     so both would paint a brand-yellow (or red) slab across the column. Match the chip
     tones and drop the fade to the panel colour. */
  .referent_container--inverse, .referent_container--green {
    background-color: #3d3d1a !important; }
  .referent_container--red { background-color: #4a1e1e !important; }
  .referent_container--inverse .referent_container-excerpt_container::before,
  .referent_container--green .referent_container-excerpt_container::before {
    background-image: linear-gradient(rgba(61, 61, 26, 0), #3d3d1a 85%) !important; }
  .referent_container--red .referent_container-excerpt_container::before {
    background-image: linear-gradient(rgba(74, 30, 30, 0), #4a1e1e 85%) !important; }
  /* standalone annotation (artist profile contributions): the caret pointing to the
     card is a rotated ::before square painted pure white -> match the card surface.
     Its top+left borders are the only two edges the rotation leaves visible and the
     site draws them #e9e9e9; the blanket border reset is `*`, which does not match
     pseudo-elements, so they survive as a bright chevron outline on the dark card. */
  .standalone_annotation { background-color: #1c2128 !important; }
  .standalone_annotation-referent_fragment--with_caret::before,
  .standalone_annotation-referent_fragment::before {
    background-color: #1c2128 !important; border-color: #2d333b !important; }

  /* ====================================================================
     MOBILE-ONLY surfaces (legacy "snarly" mobile + the AMP bundle)
     Genius serves layout by USER-AGENT: the song page is React, the artist
     page is legacy snarly, and album/article pages are AMP documents
     (<html class="i-amphtml-singledoc">). None of these are reachable by
     narrowing a desktop viewport, so a desktop-only pass never sees them.
     ==================================================================== */

  /* "Show all songs / albums" slide-over: the panel ships pure white and the site's
     own song cards inside it are already dark, so the panel reads as a white frame
     with the heading ("<Artist> Songs", lifted light by our typography) invisible on
     it. The ".slide_over_pane" wrapper is the transparent backdrop — only the
     scrollable panel is a surface. Click-only, so no load-time scan sees it. */
  .slide_over_pane-scrollable { background-color: #14181d !important; }

  /* AMP fixed header: a brand-yellow bar carrying a black inline-SVG wordmark and the
     "SIGN UP" link. Our shared link rule lifts that link to periwinkle (~1.9:1 on the
     yellow) and the embedded search amp-iframe is darkened by the body rule, so the
     bar renders as a yellow strip with a dark hole punched in it. Darken it like every
     other nav and lift the wordmark, which is a separate class from the React one. */
  .page_header-header {
    background-color: #0d1117 !important; border-bottom: 2px solid #ed4337 !important; }
  .page_header-logo svg, .page_header-logo svg path {
    fill: #e6edf3 !important; color: #e6edf3 !important; }
  /* The header search box is an amp-iframe loading a same-origin
     genius.com/amp_iframe_html/search.html document, so domain("genius.com") matches
     inside it. Two things hide its magnifier: the glyph ships a pure-black fill (drawn
     for the yellow bar), and the icon is position:absolute BEHIND the input, which is
     natively transparent — the shared `input` surface rule paints it opaque and buries
     the icon. Keep the field bare (its own 2px underline is the affordance) and lift
     the glyph, or the header shows an empty box with no search cue at all. */
  .search_form-text_input { background-color: transparent !important; }
  /* Typing/focus MUST re-fill the field opaquely: genius flips it to #ffff64 there, and
     that fill is what hides the magnifier sitting behind the input — left transparent,
     the query text renders straight over the glyph. Restate it as an elevated surface
     with the accent underline so the state still reads on the dark bar. */
  .search_form-text_input:focus, .search_form-text_input:valid {
    background-color: #21262d !important; border-bottom-color: #ed4337 !important; }
  .search_form-icon, .search_form-icon path {
    fill: #c4cdd6 !important; color: #c4cdd6 !important; }
  /* AMP accordion band ("TRANSLATIONS" on album pages) is a full-width white header
     between two dark sections. */
  .footer_accordion-header_with_arrow { background-color: #14181d !important; }
  /* Album description teaser: genius wraps the WHOLE preview paragraph in a bare <a> (no
     href, an AMP tap action) and carries the affordance only on the "-read_more" span, which
     it alone paints periwinkle over #222 body copy. The shared link rule reaches the whole
     paragraph, so the body has to be returned to the reading tone here or the description
     reads as one long link and the "read more »" cue dissolves into it. */
  .album_description_preview a { color: #c4cdd6 !important; }
  .album_description_preview-read_more { color: #9aa7f0 !important; }
  /* AMP tracklist "verified lyrics" badge. genius ships ONE ".checky path" black-fill rule
     for both bundles: on desktop that path is the tick sitting on a yellow <circle>, but the
     AMP variant draws the badge as two paths — a green square plus a white tick — so both go
     black and the badge reads as a hole punched in the dark row. Restore each from its own
     fill attribute; the desktop tick keys on "#000" and is left alone. */
  .checky path[fill="#27F145"] { fill: #27f145 !important; }
  .checky path[fill="#FFF"] { fill: #ffffff !important; }
  /* AMP sticky-ad chrome: the framework's own wrapper is white, so a 320px creative in
     a 390px viewport leaves white bands down both sides plus a white 4px rule above it.
     The close button is a white disc with a grey glyph baked into a data-URI SVG we
     cannot recolour — invert it so the disc goes dark and the glyph light. */
  amp-sticky-ad, amp-sticky-ad-top-padding { background-color: #14181d !important; }
  .amp-sticky-ad-close-button { filter: invert(1) !important; }
  /* AMP consent prompt: <amp-consent> is itself the full-screen dimmer AMP puts behind
     the prompt, painted rgba(255,255,255,.7) — on the dark AMP bundle that washes the
     whole page to a bright grey while the prompt is up. It sits at visibility:hidden
     until the prompt opens, so no load-time scan sees it, and the blanket "paint it
     dark" rules miss it because the wash comes from the alpha, not a light surface.
     Dim on dark instead; the prompt panel is a CHILD element and still paints on top. */
  amp-consent, amp-consent#consent_element {
    background-color: rgba(0, 0, 0, 0.7) !important; }

  /* ====================================================================
     livingtracklist.genius.com — the "Living Tracklist" microsite the nav links to.
     domain("genius.com") covers every subdomain, so this Next.js app is in scope: a
     separate stack whose only stable hooks are its CSS-module class prefixes
     ("<Component>-module__<hash>__<part>"; the hash rots, the component name does not).
     Its paper is one fixed full-viewport "Loader" section, so the base html/body rule
     never reaches it and every string the shared typography lifts lands light-on-white.
     ==================================================================== */
  [class*="Loader-module__"] { background-color: #14181d !important; }
  /* the loading counter is the one string the loader paints brand green, and the shared
     span rule greys it out — first paint then carries no colour at all */
  [class*="Loader-module__"][class*="__progress"] span { color: #01a74a !important; }
  /* The two pill CTAs keep their brand fill and carry their label in ink the fill was
     chosen for: "Explore More"/"Enter" rest on yellow with black ink, "Sweepstakes" is
     green with white. Both are <a>, so the shared link rule repaints them periwinkle at
     ~2.4:1 on their own fill — and its ":hover" half outranks a plain [class*=] selector,
     so Sweepstakes has to name the state to hold its label through a pointer. */
  [class*="MainButton-module__"], [class*="MainButton-module__"] *,
  [class*="ExploreMoreButton-module__"], [class*="ExploreMoreButton-module__"] * {
    color: #14181d !important; }
  [class*="SweepstakesButton-module__"], [class*="SweepstakesButton-module__"] *,
  [class*="SweepstakesButton-module__"]:hover, [class*="SweepstakesButton-module__"]:hover *,
  [class*="SweepstakesButton-module__"]:focus, [class*="SweepstakesButton-module__"]:focus * {
    color: #ffffff !important; }
  /* MainButton's hover/focus fill flips from the yellow to that same brand green and the
     site flips its label white with it. The rest-state rule above is !important, so
     without this the label stays dark once the fill has gone green. */
  [class*="MainButton-module__"]:hover, [class*="MainButton-module__"]:hover *,
  [class*="MainButton-module__"]:focus, [class*="MainButton-module__"]:focus * {
    color: #ffffff !important; }
  /* Decade rail: the site marks the current decade brand green (plus a bigger italic
     face), the rest black-20%, and moves to solid black on hover. Every one of those
     inks needs lifting on dark, but lifting them all alike is what erases the "you are
     here" and hover cues — give each state its own tone. The green rule also names
     :first-child because the rail rotates through a fixed slot the site styles the same
     way, and it must stay last: the active item carries the "__item" class too. */
  [class*="TrackExplorerNav-module__"][class*="__item"],
  [class*="TrackExplorerNav-module__"][class*="__item"] * { color: #c4cdd6 !important; }
  [class*="TrackExplorerNav-module__"][class*="__item"]:hover,
  [class*="TrackExplorerNav-module__"][class*="__item"]:hover * { color: #ffffff !important; }
  [class*="TrackExplorerNav-module__"][class*="__active"],
  [class*="TrackExplorerNav-module__"][class*="__active"] *,
  [class*="TrackExplorerNav-module__"][class*="__item"]:first-child,
  [class*="TrackExplorerNav-module__"][class*="__item"]:first-child * { color: #01a74a !important; }
  /* "Explore More" swaps the canvas explorer for /explore, a scrolling article rendered
     inside one fixed full-viewport "PageOverlay" whose paper is white — a second sheet of
     paper the Loader rule above never reaches, so every string the shared typography
     lifts lands light-on-white. */
  [class*="PageOverlay-module__"] { background-color: #14181d !important; }
  /* The wordmark is a <canvas> masked by loader-mask.svg: the mask cuts the glyphs, the
     element's own background-color is the UNFILLED ink and the bitmap paints only the
     green fill that wipes up over it. Black unfilled ink vanishes on a dark plate, and
     the loader carries the same canvas at 0% fill. */
  canvas[class*="LoaderLogo-module__"] { background-color: #e6edf3 !important; }
  /* The "For The Record" and panelist sections are solid brand-green plates the site
     pairs with white copy; the shared p/span/a rules dull that to ~2:1 on the fill. */
  [class*="ExploreVideoInfo-module__"], [class*="ExploreVideoInfo-module__"] *,
  [class*="ExplorePanelists-module__"], [class*="ExplorePanelists-module__"] * {
    color: #ffffff !important; }
  /* /track/<slug> opens in the same overlay, and both routes separate their sections with
     full-width #ffff64 plates carrying black ink. At ~0.93 luminance those are light-bombs
     here, so take the elevated surface and let the lifted copy land on it. The "Explore
     More" rail is shared between the two routes, and on /explore the same fill arrives as
     a green -> #ffff64 gradient running straight into the footer. */
  [class*="TrackInsights-module__"][class*="__TrackInsights"],
  [class*="TrackRelated-module__"][class*="__TrackRelated"],
  [class*="ExploreMore-module__"][class*="__ExploreMore"] {
    background-color: #1c2128 !important; }
  [class*="ExploreMore-module__"][class*="__gradient"] {
    background-image: linear-gradient(#01a74a 0px, #1c2128 35%, #1c2128 100%) !important; }
  /* ...except the key-lyric marker, where that same yellow IS the signal: it is a
     highlighter drawn over one lyric line, so keep the fill and put its ink back. */
  [class*="TrackLyric-module__"] blockquote span,
  [class*="TrackLyric-module__"] blockquote span * { color: #14181d !important; }
  /* At narrow widths the lyric block collapses behind a white "more below" fade and an
     "Expand" pill. The fade is a ::after gradient, so no background-color scan sees it;
     the pill keeps the site's white fill and the black ink that fill was chosen for. */
  [class*="TrackLyric-module__"][class*="__lyric"]::after {
    background-image: linear-gradient(rgba(20, 24, 29, 0), #14181d) !important; }
  [class*="ExpandButton-module__"], [class*="ExpandButton-module__"] * { color: #14181d !important; }
  /* Under those plates sit two black-on-yellow marks: the section's Genius wordmark SVG,
     which carries no fill attribute at all and so falls back to black, and the insight
     tabs' icons, stroked/filled with currentColor off a button the shared rules leave
     black — the label span is lifted but the icon beside it is not. */
  svg[class*="TrackInsights-module__"] path { fill: #c4cdd6 !important; }
  [class*="TrackInsights-module__"] nav button { color: #c4cdd6 !important; }
  /* The current tab is marked ONLY by an opaque border while the rest ship theirs
     transparent, so the blanket border reset paints all four alike. */
  [class*="TrackInsights-module__"] nav button { border-color: transparent !important; }
  [class*="TrackInsights-module__"] nav button[aria-current="true"] {
    border-color: #c4cdd6 !important; }
  /* Its footer is natively a yellow plate carrying the Sprite/GENIUS lockup as one inline
     SVG of fill="#000" paths; the shared footer rule darkens the plate under it. The
     sibling chevron SVG in the sticky Home pill is stroked with fill="none", so key this
     to the lockup's own class instead of every path in the footer. */
  svg[class*="Footer-module__"] path { fill: #c4cdd6 !important; }
  /* The microsite's sticky bar is a bare 24px anchor the floating Home/Explore pill hangs
     off, natively transparent so the page scrolls under it; the shared footer rule fills
     it into an opaque strip across the bottom of every view. */
  footer[class*="StickyFooter-module__"] { background-color: transparent !important; }

  /* ====================================================================
     promote.genius.com — the "Promote Your Music" Shopify storefront, also in scope
     through domain(). Its own theme is already near-black, so only the two places it
     paints white need us. None of these class names exist on genius.com proper.
     ==================================================================== */
  /* The hero subhead sits on genius's own yellow plate and carries the black ink that
     plate was chosen for; the shared span rule lifts it to ~1.5:1 on the yellow. The H1
     next to it is a BLACK box and must keep the lifted ink. */
  .banner__text.subtitle, .banner__text.subtitle * { color: #14181d !important; }
  /* Dawn's ".button" is one WHITE pill carrying near-black ink, in both element forms,
     with or without a "--primary" modifier, and with its label sometimes in a nested
     <span>. The shared link rule repaints the <a> form periwinkle at 2.3:1 and the
     shared span rule washes the <button> form's label to 1.6:1, both ON the white fill.
     None of these class names exist on genius.com proper. */
  a.button, a.button *, button.button, button.button *,
  .shopify-challenge__button, .shopify-challenge__button *,
  .customer button, .customer button * { color: #212121 !important; }
  /* ...except the outline variants, which Dawn fills TRANSPARENT: they sit on the
     store's own near-black panels and take a light label, not the pill's dark ink. */
  a.button--secondary, a.button--secondary *,
  a.button--tertiary, a.button--tertiary * { color: #9aa7f0 !important; }
  button.button--secondary, button.button--secondary *,
  button.button--tertiary, button.button--tertiary * { color: #e6edf3 !important; }
  /* The header cart badge is a WHITE disc carrying near-black ink, and it sits inside the
     cart <a>, so the shared link rule repaints its count periwinkle at 2.3:1 on the disc.
     It only renders once the cart is non-empty. */
  .cart-count-bubble, .cart-count-bubble * { color: #212121 !important; }
  /* The newsletter pop-up is a Booster widget rendered in an about:blank subframe that
     inherits the store's origin, so this block applies inside it: its card is white
     while the heading our typography lifts sits on top of it, and its body line is the
     one string the widget paints pure black. */
  .ba_widget_main_design { background-color: #1c2128 !important; }
  .ba_initial_state_body { color: #c4cdd6 !important; }

  /* ====================================================================
     Forms / inputs (shared)
     ==================================================================== */
  input, textarea, select {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  input::placeholder, textarea::placeholder { color: #8b949e !important; }

  /* ====================================================================
     Footer (both React + legacy)
     ==================================================================== */
  [class*="PageFooter-desktop__Container"], [class*="PageFooter"][class*="Container"],
  [class*="PageFooter-shared"], footer, .footer, .page_footer {
    background-color: #0d1117 !important; border-color: #2d333b !important; color: #c4cdd6 !important; }
  [class*="PageFooter"] a, [class*="PageFooterArtistLinks__Link"],
  [class*="PageFooterHotSongLinks__Link"], [class*="PageFooter-desktop__Link"],
  footer a, .footer a { color: #9aa7f0 !important; }
  [class*="PageFooter-desktop__FinePrint"], [class*="PageFooter-desktop__Label"] { color: #8b949e !important; }
  [class*="PageFooterSocial__Slogan"] { color: #e6edf3 !important; }

  /* ---- Image loading placeholders: light-grey skeleton -> dark ---- */
  [class*="SizedImage__Container"], [class*="SizedImage__Image"],
  .clipped_background, .mini_card-thumbnail, .mini_article_card-thumbnail,
  .cover_art, .vertical_album_card-cover_art, [class*="image_with_overlay"] {
    background-color: #1c2128 !important; }

  /* ---- Ad surrounds: dark frame + dark loading slot, don't theme iframe content ---- */
  [class*="SectionLeaderboard__Container"], [class*="ChartHeader-desktop__AdContainer"],
  [class*="LyricsSidebarAd__"], [class*="SongCommentsWithAds__Footer"],
  [id*="ad_"], [class*="dfp"], [class*="Leaderboard"] {
    background-color: #14181d !important; }
  /* Google DFP ad slots have stable ids — darken the empty/loading slot background */
  [id^="div-gpt-ad-"], [id*="google_ads_iframe"], [id$="__container__"], ins.adsbygoogle {
    background-color: #14181d !important; }
  /* Each DFP slot ships a sibling placeholder box (hashed styled-component class)
     that paints a light-grey #e9e9e9 rectangle while the slot is empty — a glaring
     light block in the lyrics column + leaderboards. It's always the next sibling
     of the [id^="div-gpt-ad-"] slot, so target it structurally. */
  [id^="div-gpt-ad-"] + div { background-color: #14181d !important; }

  /* ====================================================================
     OneTrust consent surfaces
     The banner every first-time visitor lands on ("#onetrust-banner-sdk") and the
     preference centre behind the "Privacy Preferences" link in every footer
     ("#onetrust-pc-sdk"). Both ship a pure-white panel, and their copy is MIXED:
     OneTrust paints most of it black with its own !important while the shared
     p/span/button typography lifts the rest to light — so today half the text is
     already invisible ON the white panel (the banner's purposes paragraph, the whole
     preference-centre body and its category tabs). Darken both panels and lift ALL the
     copy. These are OneTrust's own SDK ids, stable across builds.
     ==================================================================== */
  #onetrust-banner-sdk, #onetrust-pc-sdk, #onetrust-pc-sdk .ot-active-menu {
    background-color: #1c2128 !important; }
  #onetrust-pc-sdk .category-menu-switch-handler,
  #onetrust-pc-sdk .ot-pc-footer-logo { background-color: #21262d !important; }
  /* The IAB vendor list behind "List of IAB Vendors" is a second view inside the same
     panel, and its two chrome rows keep OneTrust's own white fill: the "Allow All
     Consent" select-all band ("#ot-sel-blk") and the search row ("#ot-search-cntr").
     The panel rule above only paints the outer container, so the band renders as a
     white slab carrying our lifted light label. Both are unclassed <div>s under those
     two SDK ids, and the view only exists once the vendor list is opened. */
  #onetrust-pc-sdk #ot-sel-blk { background-color: #21262d !important; }
  #onetrust-pc-sdk #ot-search-cntr { background-color: #1c2128 !important; }
  /* ...and expanding a vendor row opens a white "ot-ven-dets" table (lifespan, data
     declaration, purposes) whose rows carry no fill of their own, so the whole block
     reads as our light copy on white. */
  #onetrust-pc-sdk .ot-ven-dets { background-color: #21262d !important; }
  #onetrust-banner-sdk, #onetrust-banner-sdk *,
  #onetrust-pc-sdk, #onetrust-pc-sdk * {
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }
  #onetrust-banner-sdk a, #onetrust-pc-sdk a {
    color: #9aa7f0 !important; -webkit-text-fill-color: #9aa7f0 !important; }
  /* every action here is a button: either a solid brand-black fill or a bare text
     button on the panel — white reads on both */
  #onetrust-banner-sdk button, #onetrust-banner-sdk button *,
  #onetrust-pc-sdk button, #onetrust-pc-sdk button * {
    color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; }
  /* ...except the banner's secondary "Show Purposes", which OneTrust fills pure WHITE.
     It is invisible against the white banner, so it reads as a text button there; on the
     dark panel it becomes a white slab swallowing its own white label. Strip the fill. */
  #onetrust-banner-sdk #onetrust-pc-btn-handler {
    background-color: transparent !important; }
  /* the selected category is marked ONLY by a 10px left bar, and every other item ships
     that bar transparent — the blanket border reset paints them all alike, so the
     "you are here" cue disappears. Clear them, then repaint the active one brand red. */
  #onetrust-pc-sdk .category-menu-switch-handler { border-left-color: transparent !important; }
  #onetrust-pc-sdk .ot-active-menu.category-menu-switch-handler {
    border-left-color: #ed4337 !important; }
  /* the OneTrust wordmarks (header + "Powered by" footer) are black raster/SVG logos */
  #onetrust-pc-sdk .ot-pc-logo img, #onetrust-pc-sdk .ot-pc-footer-logo img {
    filter: invert(1) !important; }
  /* The preference centre's category list is its own scroll container and OneTrust paints
     the thumb #c1c1c1 with an explicit ::-webkit-scrollbar-thumb rule, so `color-scheme:
     dark` never gets a say: a bright 11px bar runs down the middle of the dark panel.
     Repaint both the standard and the WebKit scrollbar. */
  #onetrust-banner-sdk, #onetrust-pc-sdk, #onetrust-pc-sdk .ot-tab-list,
  #onetrust-pc-sdk .ot-pc-scrollbar, #onetrust-pc-sdk .ot-grps-cntr {
    scrollbar-color: #4a525c #1c2128 !important; }
  #onetrust-banner-sdk::-webkit-scrollbar-track,
  #onetrust-pc-sdk ::-webkit-scrollbar-track {
    background: #1c2128 !important; }
  #onetrust-banner-sdk::-webkit-scrollbar-thumb,
  #onetrust-pc-sdk ::-webkit-scrollbar-thumb {
    background: #4a525c !important; }

  /* ---- Misc ---- */
  hr { border-color: #2d333b !important; }
  ::selection { background-color: #ed4337 !important; color: #ffffff !important; }
  /* generic safety net: any element painted pure-white or near-white inline */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"] { background-color: #1c2128 !important; }
}

@-moz-document url-prefix("https://genius.com/amp_iframe_html/") {
/* ============================================================
     AMP header widgets embedded as same-origin <amp-iframe> documents
     (currently only search.html, the header search field).
     These are chrome fragments, not pages: they render INSIDE
     ".page_header-header" and are natively fully transparent, so the
     header colour is what shows through them. domain("genius.com")
     matches inside the frame, so the base rule above paints their
     document the page base (#14181d) and each widget cuts a lighter
     rectangle into the darkened header bar. Restore transparency —
     tracking the header hex here instead would desync the moment the
     header rule changes.
     ============================================================ */
  html, body { background-color: transparent !important; }
}
